/* ====== 视图切换 ====== */
const homeViews = {weekly:'view-weekly', voice:'view-voice', serve:'view-serve'};
function go(id){
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('on'));
  document.getElementById(id).classList.add('on');
  if(id!=='view-weekly'&&id!=='view-voice'&&id!=='view-serve'){
    document.getElementById('screen').scrollTop = 0;
    return;
  }
  setTab(id);
}
function setTab(id){
  const tab = Object.keys(homeViews).find(k=>homeViews[k]===id)||'weekly';
  document.querySelectorAll('.tabbar > div').forEach(t=>t.classList.toggle('on', t.dataset.tab===tab));
  document.getElementById('screen').scrollTop = 0;
}
document.querySelectorAll('.tabbar > div').forEach(t=>t.addEventListener('click',()=>go(homeViews[t.dataset.tab])));

/* ====== Toast ====== */
let toastTimer;
function toast(msg){
  const t = document.getElementById('toast');
  t.textContent = '✓ ' + msg;
  t.classList.add('on');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('on'), 2200);
}

/* ====== 语音留言 ====== */
let recording = false;
function recordVoice(){
  const btn = document.getElementById('recordBtn');
  recording = !recording;
  if(recording){
    btn.classList.add('recording');
    btn.innerHTML = '<span class="iconify" data-icon="ph:stop-fill"></span> 正在录音…松开发送';
  }else{
    btn.classList.remove('recording');
    btn.innerHTML = '<span class="iconify" data-icon="ph:microphone"></span> 按住说话 · 松开发送';
    const chat = document.getElementById('voiceChat');
    const m = document.createElement('div');
    m.className = 'msg voice-me';
    m.innerHTML = '<div class="ava"><span class="iconify" data-icon="ph:user"></span></div><div class="bub">闺女，好好吃饭，别让奶奶操心。<div class="voice-bar" style="background:rgba(255,255,255,.22)"><span class="iconify" data-icon="ph:play-fill"></span><div class="v-track"><i style="width:100%;background:#fff"></i></div><span class="v-time" style="color:#fff">00:12</span></div><div style="font-size:10px;color:rgba(255,255,255,.7);margin-top:6px">已发送 · 小雨会收到提醒</div></div>';
    chat.appendChild(m);
    m.scrollIntoView({behavior:'smooth', block:'nearest'});
    toast('留言已发送，小雨会收到提醒');
  }
}

/* ====== 大字版 ====== */
function toggleBig(el){
  el.classList.toggle('on');
  const on = el.classList.contains('on');
  const screen = document.getElementById('phoneBox');
  if(on){ screen.style.setProperty('--big', '1'); document.querySelector('.phone-screen').style.fontSize = '1.18em'; }
  else{ screen.style.removeProperty('--big'); document.querySelector('.phone-screen').style.fontSize = ''; }
  toast(on ? '大字版已开启' : '已恢复常规模式');
}
function speakBig(btn){
  btn.innerHTML = '<span class="iconify" data-icon="ph:stop-circle"></span> 正在朗读…（模拟）';
  setTimeout(()=>{ btn.innerHTML = '<span class="iconify" data-icon="ph:megaphone"></span> 点这里，读给我听'; toast('已朗读：小雨本周表现很好，84 分'); }, 2600);
}


/* ===== 由构建脚本注入：onclick 行为迁移（CSP 兼容层） ===== */
(function () {
  function bindExpr(el) {
    if (el.__boundOnclick) return;
    var expr = el.getAttribute('onclick');
    if (!expr) return;
    el.__boundOnclick = true;
    el.removeAttribute('onclick');
    var m = expr.match(/^\s*([A-Za-z_$][\w$]*)\s*\((.*)\)\s*;?\s*$/);
    if (!m) return;
    var fn = window[m[1]];
    if (typeof fn !== 'function') return;
    var rawArgs = m[2] ? m[2].split(',') : [];
    var args = rawArgs.map(function (s) {
      s = s.trim();
      if (/^['"][\s\S]*['"]$/.test(s)) return { type: 'str', v: s.slice(1, -1) };
      if (s === 'this') return { type: 'this' };
      return { type: 'ident', v: s };
    });
    el.addEventListener('click', function (ev) {
      var real = args.map(function (a) {
        if (a.type === 'str') return a.v;
        if (a.type === 'this') return el;
        return window[a.v] !== undefined ? window[a.v] : a.v;
      });
      try { fn.apply(null, real); } catch (e) { /* 业务异常由统一层处理 */ }
    });
  }
  document.querySelectorAll('[onclick]').forEach(bindExpr);
  var mo = new MutationObserver(function (muts) {
    muts.forEach(function (mut) {
      mut.addedNodes.forEach(function (node) {
        if (node.nodeType !== 1) return;
        if (node.hasAttribute && node.hasAttribute('onclick')) bindExpr(node);
        node.querySelectorAll && node.querySelectorAll('[onclick]').forEach(bindExpr);
      });
    });
  });
  mo.observe(document.documentElement, { childList: true, subtree: true });
})();
